 15→// testBinaryDir creates a temp directory with a mock entire-agent-test binary.
 16→// The binary is a shell script implementing the protocol.
 17→func testBinaryDir(t *testing.T, script string) string {
 18→	t.Helper()
 19→
 20→	dir := t.TempDir()
 21→
 22→	name := "entire-agent-test"
 23→	if runtime.GOOS == "windows" {
 24→		name += ".bat"
 25→	}
 26→
 27→	path := filepath.Join(dir, name)
 28→	if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
 29→		t.Fatalf("write mock binary: %v", err)
 30→	}
 31→
 32→	return path
 33→}
