 35→// mockInfoScript returns a shell script that responds to "info" with the given JSON.
 36→func mockInfoScript(infoJSON string) string {
 37→	return `#!/bin/sh
 38→case "$1" in
 39→  info)
 40→    echo '` + infoJSON + `'
 41→    ;;
 42→  detect)
 43→    echo '{"present": true}'
 44→    ;;
 45→  get-session-dir)
 46→    echo '{"session_dir": "/tmp/sessions"}'
 47→    ;;
 48→  resolve-session-file)
 49→    echo '{"session_file": "/tmp/sessions/test.jsonl"}'
 50→    ;;
 51→  get-session-id)
 52→    echo '{"session_id": "test-session-123"}'
 53→    ;;
 54→  read-session)
 55→    echo '{"session_id":"s1","agent_name":"test","repo_path":"/repo","session_ref":"ref"}'
 56→    ;;
 57→  write-session)
 58→    exit 0
 59→    ;;
 60→  format-resume-command)
 61→    echo '{"command": "test-agent resume '$3'"}'
 62→    ;;
 63→  read-transcript)
 64→    echo 'raw transcript data'
 65→    ;;
 66→  chunk-transcript)
 67→    echo '{"chunks": ["Y2h1bms="]}'
 68→    ;;
 69→  reassemble-transcript)
 70→    cat
 71→    ;;
 72→  parse-hook)
 73→    echo 'null'
 74→    ;;
 75→  install-hooks)
 76→    echo '{"hooks_installed": 2}'
 77→    ;;
 78→  uninstall-hooks)
 79→    exit 0
 80→    ;;
 81→  are-hooks-installed)
 82→    echo '{"installed": true}'
 83→    ;;
 84→  get-transcript-position)
 85→    echo '{"position": 42}'
 86→    ;;
 87→  extract-modified-files)
 88→    echo '{"files": ["a.go", "b.go"], "current_position": 10}'
 89→    ;;
 90→  extract-prompts)
 91→    echo '{"prompts": ["hello", "world"]}'
 92→    ;;
 93→  extract-summary)
 94→    echo '{"summary": "test summary", "has_summary": true}'
 95→    ;;
 96→  *)
 97→    echo "unknown subcommand: $1" >&2
 98→    exit 1
 99→    ;;
100→esac
101→`
102→}
