123→func TestRun_AppliesTimeoutWhenNoDeadline(t *testing.T) {
124→	// Not parallel: mutates package-level defaultRunTimeout.
125→	if _, err := exec.LookPath("sh"); err != nil {
126→		t.Skip("sh not available")
127→	}
128→
129→	script := `#!/bin/sh
130→case "$1" in
131→  info)
132→    echo '` + validInfoJSON + `'
133→    ;;
134→  slow)
135→    exec sleep 60
136→    ;;
137→esac
138→`
139→	binPath := testBinaryDir(t, script)
140→	ea, err := New(context.Background(), binPath)
141→	if err != nil {
142→		t.Fatalf("New: %v", err)
143→	}
144→
145→	// Temporarily override the default timeout to keep the test fast.
146→	orig := defaultRunTimeout
147→	defaultRunTimeout = 1 * time.Second
148→	t.Cleanup(func() { defaultRunTimeout = orig })
149→
150→	start := time.Now()
151→	_, err = ea.run(context.Background(), nil, "slow")
152→	elapsed := time.Since(start)
153→
154→	if err == nil {
155→		t.Fatal("expected timeout error, got nil")
156→	}
157→	// Should be killed around 1s, not 60s.
158→	if elapsed >= 5*time.Second {
159→		t.Errorf("run() took %v; default timeout was not applied", elapsed)
160→	}
161→}
