163→func TestRun_RespectsExistingDeadline(t *testing.T) {
164→	t.Parallel()
165→
166→	if _, err := exec.LookPath("sh"); err != nil {
167→		t.Skip("sh not available")
168→	}
169→
170→	script := `#!/bin/sh
171→case "$1" in
172→  info)
173→    echo '` + validInfoJSON + `'
174→    ;;
175→  slow)
176→    exec sleep 60
177→    ;;
178→esac
179→`
180→	binPath := testBinaryDir(t, script)
181→	ea, err := New(context.Background(), binPath)
182→	if err != nil {
183→		t.Fatalf("New: %v", err)
184→	}
185→
186→	// Provide a context with a short deadline. run() should respect it
187→	// and NOT override with its own (longer) timeout.
188→	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
189→	defer cancel()
190→
191→	start := time.Now()
192→	_, err = ea.run(ctx, nil, "slow")
193→	elapsed := time.Since(start)
194→
195→	if err == nil {
196→		t.Fatal("expected timeout error, got nil")
197→	}
198→	if elapsed >= 5*time.Second {
199→		t.Errorf("run() took %v; caller's deadline was not respected", elapsed)
200→	}
201→}
